// shouldSkipPendingReview checks whether a pending REVIEW.md should block a new
// review. Returns true if the review is from the current session and still fresh.
// Deletes stale reviews (different session or older than TTL) and returns false.
func shouldSkipPendingReview(repoRoot, currentSessionID string) bool {
	reviewPath := filepath.Join(repoRoot, wingmanReviewFile)
	if _, err := os.Stat(reviewPath); err != nil {
		return false // No REVIEW.md exists
	}

	// Load state to check ownership
	state := loadWingmanStateDirect(repoRoot)
	if state == nil {
		// REVIEW.md exists but no state file — orphan, clean up
		_ = os.Remove(reviewPath)
		return false
	}

	// Different session — stale review from a previous session
	if state.SessionID != currentSessionID {
		_ = os.Remove(reviewPath)
		return false
	}

	// Same session but older than TTL — stale
	if time.Since(state.ReviewedAt) > wingmanStaleReviewTTL {
		_ = os.Remove(reviewPath)
		return false
	}

	// Same session, still fresh — skip (don't overwrite)
	return true
}

